// SPDX-License-Identifier: MIT
pragma solidity ^0.8.17;

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title MultiSigVault
 * @notice A multi-signature vault that requires k-of-n signatures to execute transactions.
 * @dev Uses EIP-712 structured signing for security. All arithmetic is checked (Solidity 0.8+).
 */
contract MultiSigVault is Ownable {
    using ECDSA for bytes32;

    struct Transaction {
        address to;
        uint256 value;
        bytes data;
        bool executed;
        uint256 confirmations;
    }

    uint256 public requiredConfirmations;
    address[] public signers;
    mapping(address => bool) public isSigner;
    mapping(uint256 => mapping(address => bool)) public hasConfirmed;
    Transaction[] public transactions;

    // Nonce for meta-transactions to prevent replay
    mapping(address => uint256) public nonces;

    // Domain separator for EIP-712
    bytes32 public DOMAIN_SEPARATOR;

    // Permit typehash
    bytes32 public constant PERMIT_TYPEHASH = keccak256(
        "Permit(address signer,uint256 txIndex,uint256 nonce,uint256 deadline)"
    );

    // Batch permit typehash
    bytes32 public constant BATCH_PERMIT_TYPEHASH = keccak256(
        "BatchPermit(address signer,uint256[] txIndices,uint256 nonce,uint256 deadline)"
    );

    event TransactionSubmitted(uint256 indexed txIndex, address indexed submitter);
    event TransactionConfirmed(uint256 indexed txIndex, address indexed signer);
    event TransactionExecuted(uint256 indexed txIndex);
    event SignerAdded(address indexed signer);
    event SignerRemoved(address indexed signer);

    modifier onlySigner() {
        require(isSigner[msg.sender], "Not a signer");
        _;
    }

    modifier txExists(uint256 _txIndex) {
        require(_txIndex < transactions.length, "Tx does not exist");
        _;
    }

    modifier notExecuted(uint256 _txIndex) {
        require(!transactions[_txIndex].executed, "Tx already executed");
        _;
    }

    constructor(address[] memory _signers, uint256 _requiredConfirmations) {
        require(_signers.length >= _requiredConfirmations, "Invalid confirmations");
        require(_requiredConfirmations > 0, "Need at least 1 confirmation");

        for (uint256 i = 0; i < _signers.length; i++) {
            address signer = _signers[i];
            require(signer != address(0), "Invalid signer");
            require(!isSigner[signer], "Duplicate signer");
            isSigner[signer] = true;
            signers.push(signer);
        }

        requiredConfirmations = _requiredConfirmations;

        DOMAIN_SEPARATOR = keccak256(
            abi.encode(
                keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"),
                keccak256(bytes("MultiSigVault")),
                keccak256(bytes("1")),
                block.chainid,
                address(this)
            )
        );
    }

    receive() external payable {}

    function submitTransaction(address _to, uint256 _value, bytes calldata _data)
        external
        onlySigner
        returns (uint256)
    {
        uint256 txIndex = transactions.length;
        transactions.push(Transaction({
            to: _to,
            value: _value,
            data: _data,
            executed: false,
            confirmations: 0
        }));
        emit TransactionSubmitted(txIndex, msg.sender);
        return txIndex;
    }

    function confirmTransaction(uint256 _txIndex)
        external
        onlySigner
        txExists(_txIndex)
        notExecuted(_txIndex)
    {
        require(!hasConfirmed[_txIndex][msg.sender], "Already confirmed");
        Transaction storage txn = transactions[_txIndex];
        txn.confirmations += 1;
        hasConfirmed[_txIndex][msg.sender] = true;
        emit TransactionConfirmed(_txIndex, msg.sender);
    }

    /**
     * @notice Allows off-chain confirmation via EIP-712 signature.
     * @dev This enables gasless confirmations for signers.
     */
    function confirmWithPermit(
        address signer,
        uint256 txIndex,
        uint256 deadline,
        uint8 v,
        bytes32 r,
        bytes32 s
    )
        external
        txExists(txIndex)
        notExecuted(txIndex)
    {
        require(block.timestamp <= deadline, "Permit expired");
        require(isSigner[signer], "Not a signer");
        require(!hasConfirmed[txIndex][signer], "Already confirmed");

        bytes32 structHash = _computeStructHash(signer, txIndex, nonces[signer], deadline);
        bytes32 digest = _computeDigest(structHash);

        address recovered = digest.recover(v, r, s);
        require(recovered == signer, "Invalid signature");

        nonces[signer]++;
        Transaction storage txn = transactions[txIndex];
        txn.confirmations += 1;
        hasConfirmed[txIndex][signer] = true;
        emit TransactionConfirmed(txIndex, signer);
    }

    /**
     * @notice Batch confirm multiple transactions with a single signature.
     * @dev Uses abi.encode for proper EIP-712 encoding of dynamic arrays.
     * @param signer The address of the signer
     * @param txIndices Array of transaction indices to confirm
     * @param deadline Signature expiry timestamp
     */
    function batchConfirmWithPermit(
        address signer,
        uint256[] calldata txIndices,
        uint256 deadline,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external {
        require(block.timestamp <= deadline, "Permit expired");
        require(isSigner[signer], "Not a signer");
        require(txIndices.length > 0, "Empty batch");

        // Compute batch hash for signature verification using proper EIP-712 encoding
        bytes32 batchHash = _computeBatchHash(signer, txIndices, nonces[signer], deadline);
        bytes32 digest = _computeDigest(batchHash);

        address recovered = digest.recover(v, r, s);
        require(recovered == signer, "Invalid signature");

        nonces[signer]++;

        for (uint256 i = 0; i < txIndices.length; i++) {
            uint256 txIndex = txIndices[i];
            require(txIndex < transactions.length, "Tx does not exist");
            require(!transactions[txIndex].executed, "Tx already executed");
            if (!hasConfirmed[txIndex][signer]) {
                transactions[txIndex].confirmations += 1;
                hasConfirmed[txIndex][signer] = true;
                emit TransactionConfirmed(txIndex, signer);
            }
        }
    }

    function executeTransaction(uint256 _txIndex)
        external
        onlySigner
        txExists(_txIndex)
        notExecuted(_txIndex)
    {
        Transaction storage txn = transactions[_txIndex];
        require(txn.confirmations >= requiredConfirmations, "Not enough confirmations");

        txn.executed = true;
        (bool success, ) = txn.to.call{value: txn.value}(txn.data);
        require(success, "Tx execution failed");
        emit TransactionExecuted(_txIndex);
    }

    // ============ Internal Helpers ============

    /**
     * @dev Computes the struct hash for a single permit following EIP-712.
     * NOTE: Using abi.encode (not encodePacked) for proper struct encoding.
     */
    function _computeStructHash(
        address signer,
        uint256 txIndex,
        uint256 nonce,
        uint256 deadline
    ) internal pure returns (bytes32) {
        return keccak256(
            abi.encode(
                PERMIT_TYPEHASH,
                signer,
                txIndex,
                nonce,
                deadline
            )
        );
    }

    /**
     * @dev Computes the batch hash for multiple tx confirmations.
     * Following EIP-712: dynamic types are encoded as keccak256 of their encoding.
     * Uses abi.encode for the outer struct to prevent hash collisions.
     */
    function _computeBatchHash(
        address signer,
        uint256[] calldata txIndices,
        uint256 nonce,
        uint256 deadline
    ) internal pure returns (bytes32) {
        return keccak256(
            abi.encode(
                BATCH_PERMIT_TYPEHASH,
                signer,
                keccak256(abi.encodePacked(txIndices)),
                nonce,
                deadline
            )
        );
    }

    /**
     * @dev Computes EIP-712 digest. Uses encodePacked per EIP-712 spec
     * for the final digest (this is correct — the \x19\x01 prefix
     * followed by domain separator and struct hash is the standard).
     */
    function _computeDigest(bytes32 structHash) internal view returns (bytes32) {
        return keccak256(
            abi.encodePacked("\x19\x01", DOMAIN_SEPARATOR, structHash)
        );
    }

    // ============ View Functions ============

    function getTransactionCount() external view returns (uint256) {
        return transactions.length;
    }

    function getSigners() external view returns (address[] memory) {
        return signers;
    }
}
